"""Practical homeowner tools and a shorter, task-first homepage."""
import html
import re
import shutil
from editorial import write_editorial_page


def section_range(text, marker):
    start = text.index(marker)
    depth = 0
    for token in re.finditer(r'</?section\b[^>]*>', text[start:]):
        depth += -1 if token.group().startswith('</') else 1
        if depth == 0:
            return start, start + token.end()
    raise ValueError('Unclosed section: ' + marker)


def add(out, origin, pages):
    root = out.parent
    path = out / 'index.html'
    s = path.read_text()
    a, b = section_range(s, '<section class="neighbor-welcome"')
    s = s[:a] + s[b:]
    a, b = section_range(s, '<section class="neighbor-layout"')
    feed = s[a:b]
    s = s[:a] + s[b:]
    # Remove repeated pitches; keep useful directory, guides, coverage and business applications.
    for marker in ['<section class="section"', '<section class="project-invite"', '<section class="origin-story"', '<section class="home-journal"', '<section class="trust-section wrap"', '<section class="feature"', '<section class="editorial"']:
        while marker in s:
            a, b = section_range(s, marker)
            s = s[:a] + s[b:]
    s = re.sub(r'<div class="concierge-feature">.*?</div>(?=<div class="concierge-finder")', '''<div class="concierge-feature"><div class="eyebrow">LOCAL HELP. A CLEAR NEXT STEP.</div><h1 id="hero-title">A home to love.<br><em>People to count on.</em></h1><p>Find the right local business, get your project together, and feel better about the next decision.</p><div class="concierge-feature-actions"><a class="btn primary" href="/#find">Meet your local businesses ↗</a><a href="/my-home/">My home list <span data-home-count></span> →</a></div><div class="workbench-hero-photo"><img src="/assets/valley-stone-home.jpg" width="1536" height="1024" alt="Illustrative Pennsylvania stone home with an autumn garden" fetchpriority="high"><span>For the place you call home.</span></div><p class="workbench-promise">Named businesses. Direct contact. No account needed.</p></div>''', s, count=1, flags=re.S)
    s = s.replace('Find help or save a home project', 'Find the right local help')
    tools = '''<section class="workbench-tools" aria-labelledby="tools-title"><div class="workbench-section-heading"><div><div class="eyebrow">A LITTLE HELP BEFORE YOU HIRE.</div><h2 id="tools-title">Less guesswork.<br><em>Better conversations.</em></h2></div><p>Useful tools for the decisions between<br>“we should do that” and “let’s get it done.”</p></div><div class="workbench-tool-grid"><a href="/project-kit/" class="workbench-tool"><span class="workbench-tool-icon" aria-hidden="true">01 / PREPARE</span><h3>Make the first call count.</h3><p>A short, project-specific checklist and a ready-to-copy conversation sheet.</p><strong>Build my project sheet ↗</strong></a><a href="/compare/" class="workbench-tool"><span class="workbench-tool-icon" aria-hidden="true">02 / COMPARE</span><h3>Two prices. Same job?</h3><p>Put the scope, allowances, payment terms and missing details side by side.</p><strong>Compare my estimates ↗</strong></a><a href="/my-home/" class="workbench-tool"><span class="workbench-tool-icon" aria-hidden="true">03 / KEEP TRACK</span><h3>Get “someday” on a list.</h3><p>Save the projects you have in mind, track progress and find the business again.</p><strong>Open My home list <span data-home-count></span> ↗</strong></a></div></section>'''
    marker = '<section class="read-section"'
    s = s.replace(marker, tools + feed + marker, 1)
    s = s.replace('Good work starts with good people.', 'Your next call starts with a name.')
    path.write_text(s)

    kit = '''<div class="wrap workbench-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Project preparation</div><div class="workbench-page-head"><div class="eyebrow">ONE CLEAR CONVERSATION.</div><h1>A little prep.<br><em>A much better start.</em></h1><p>Choose the work, capture the useful details and bring a clear project sheet to the business. Nothing here sends an inquiry.</p></div><div class="workbench-app" id="project-kit" hidden><section class="workbench-inputs" aria-label="Project details"><label class="workbench-field">What are you planning?<select id="kit-intent"></select></label><label class="workbench-field">Where are you with it?<select id="kit-stage"><option value="Exploring options">Exploring options</option><option value="Ready to discuss the work">Ready to discuss the work</option><option value="Comparing written estimates">Comparing written estimates</option></select></label><label class="workbench-field">What would you like to change?<textarea id="kit-goal" rows="3" maxlength="1500" placeholder="Example: the upstairs bedroom never feels comfortable."></textarea></label><label class="workbench-field">When would you like the work done?<select id="kit-timing"><option>Flexible / still planning</option><option>As soon as the business is available</option><option>Within the next month</option><option>Within the next 3 months</option><option>Later this year</option></select></label><label class="workbench-field">Useful details or questions <span>(optional)</span><textarea id="kit-notes" rows="4" maxlength="2500" placeholder="Equipment type, affected rooms, approximate measurements, access, or what you want the estimate to explain. Avoid personal contact details."></textarea></label><p class="workbench-local-note">This sheet stays in this open page. It is not saved when you leave. Copy or print it to keep it.</p></section><section class="workbench-output" aria-label="Your project sheet"><div class="workbench-output-top"><span class="eyebrow">YOUR PROJECT SHEET</span><span class="workbench-paper-mark" aria-hidden="true">w.</span></div><h2 id="kit-title">Plan your project</h2><p id="kit-context"></p><h3>Bring to the conversation</h3><ul id="kit-questions"></ul><h3>Before agreeing to the work</h3><ul><li>Confirm coverage for your address and any visit or estimate charge.</li><li>Ask for the work, exclusions, cleanup and permit responsibilities in writing.</li><li>Confirm timing, payment milestones and warranty terms.</li></ul><div id="kit-preview" class="workbench-sheet-preview"></div><div id="kit-business" class="workbench-business"></div><div class="workbench-actions"><button class="btn primary" type="button" id="kit-copy">Copy project sheet</button><button class="btn outline" type="button" data-tool-print>Print / save as PDF ↗</button></div><p id="kit-status" class="workbench-status" role="status" aria-live="polite"></p><textarea id="kit-copy-fallback" aria-label="Project sheet to copy" readonly hidden></textarea></section></div><noscript><p>The interactive sheet needs JavaScript. You can still <a href="/before-you-approve/">use the proposal checklist</a> or <a href="/#find">find a local business</a>.</p></noscript><p class="workbench-endnote">For an active service problem, call the business to discuss the appropriate visit. This tool does not diagnose equipment or confirm appointment availability.</p></div>'''
    write_editorial_page(out, origin, pages, '/project-kit/', 'Prepare your home project', 'Build a useful project sheet with questions, scope and timing before calling a local home-service business. No account or inquiry required.', kit)
    compare = '''<div class="wrap workbench-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Compare estimates</div><div class="workbench-page-head"><div class="eyebrow">LOOK PAST THE TOTAL.</div><h1>Compare the work.<br><em>Then compare the price.</em></h1><p>Check both estimates for the same work, materials and payment terms. Add what each business has put in writing.</p></div><div id="estimate-comparison" hidden><div class="workbench-comparison-top"><label class="workbench-field">What kind of project?<select id="compare-kind"><option value="general">Home project</option><option value="hvac">Heating, cooling or hot water</option><option value="painting">Painting & drywall</option><option value="remodeling">Carpentry, windows or remodeling</option></select></label><div class="workbench-actions"><button class="btn primary" type="button" data-tool-print>Print / save as PDF ↗</button><button class="btn outline" type="button" id="compare-copy-questions">Copy questions to ask</button><button class="btn outline" type="button" id="compare-clear">Clear entries</button></div></div><p id="compare-copy-status" role="status" aria-live="polite"></p><div class="workbench-comparison-summary" id="compare-summary" role="status" aria-live="polite">Enter both total prices to see the difference. Compare scope before deciding.</div><div class="workbench-table-scroll"><table class="workbench-compare-table"><caption>Written estimate comparison — entries stay in this open page only</caption><thead><tr><th scope="col">What to compare</th><th scope="col"><label>Estimate A<input id="compare-name-a" maxlength="80" placeholder="Business or proposal A" aria-label="Name for estimate A"></label></th><th scope="col"><label>Estimate B<input id="compare-name-b" maxlength="80" placeholder="Business or proposal B" aria-label="Name for estimate B"></label></th></tr></thead><tbody id="compare-rows"></tbody></table></div><section class="workbench-open-questions"><h2>Get these in writing.</h2><textarea id="compare-copy-fallback" aria-label="Estimate questions to copy" readonly hidden></textarea><p id="compare-gaps" role="status" aria-live="polite">Start with the scope and the full installed price.</p><ul><li>What is excluded, and what could change the price?</li><li>Who handles permits, removal, protection and cleanup?</li><li>What is the payment schedule, and when is the final payment due?</li><li>Who handles a callback, and what labor and material warranties apply?</li></ul></section></div><p class="workbench-local-note">No uploads. No account. No information sent to businesses. Entries are not saved when you leave; print or save as PDF to keep your comparison.</p><noscript><p>The comparison tool needs JavaScript. <a href="/before-you-approve/">Read the proposal checklist instead →</a></p></noscript><a class="workbench-next-link" href="/project-kit/">Turn your questions into a project sheet →</a></div>'''
    write_editorial_page(out, origin, pages, '/compare/', 'Compare home-service estimates side by side', 'Compare two written home-service estimates by scope, full price, exclusions, payment schedule and warranty. Private, in-page comparison without uploads.', compare)
    for target in out.rglob('*.html'):
        content = target.read_text()
        # Tools appear in the main navigation and the footer on every page.
        content = content.replace('<a href="/#how">How it works</a>', '<a href="/project-kit/">Project tools</a>')
        content = content.replace('<a href="/delaware-valley/">Our area</a>', '<a href="/my-home/">My home <span data-home-count></span></a>')
        content = content.replace('<strong>The useful details</strong>', '<strong>The useful details</strong><a href="/project-kit/">Prepare a project</a><a href="/compare/">Compare estimates</a>', 1)
        content = re.sub(r'(<a href="/start/\?intent=([a-z]+)">Prepare my project →</a>)', lambda m: m.group(1) + '<a href="/project-kit/?intent=' + m.group(2) + '">Build a conversation sheet →</a>', content)
        content = content.replace('</head>', '<link rel="stylesheet" href="/assets/homeowner-tools.css"></head>', 1)
        content = content.replace('</body>', '<script type="module" src="/assets/homeowner-tools.js"></script></body>', 1)
        target.write_text(content)
    privacy = out / 'privacy/index.html'
    privacy.write_text(privacy.read_text().replace('</main>', '<section class="wrap project-inline"><h2>Project preparation and estimate comparison.</h2><p>These tools hold your entries in the open page only. They do not transmit entries or save them in browser storage. Leaving or refreshing the page clears them. Copying uses your device clipboard; printing or saving as PDF uses your browser. You decide where to keep or share that copy.</p></section></main>', 1))
    for name in ('homeowner-tools.css', 'homeowner-tools.js'):
        shutil.copy(root / 'assets' / name, out / 'assets' / name)
